import assert from 'node:assert/strict';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repositoryRoot = fileURLToPath(new URL('../../', import.meta.url));
const manifestPath = 'Config/Release/manifest.json';
const generatedPath = 'Config/Generated/Version.xcconfig';

export function parseReleaseManifest(source) {
  const value = JSON.parse(source);
  assert.ok(value !== null && typeof value === 'object' && !Array.isArray(value), 'Release manifest must be an object.');
  assert.deepEqual(Object.keys(value).sort(), ['build', 'packagingEnabled', 'version'], 'Release manifest has missing or unknown fields.');
  assert.equal(typeof value.version, 'string', 'Version must be a string.');
  assert.match(value.version, /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/, 'Version must contain three numeric components without leading zeros.');
  assert.ok(Number.isSafeInteger(value.build) && value.build > 0, 'Build must be a positive safe integer.');
  assert.equal(typeof value.packagingEnabled, 'boolean', 'packagingEnabled must be a boolean.');
  return { version: value.version, build: value.build, packagingEnabled: value.packagingEnabled };
}

export function renderXcodeVersionConfiguration(manifestSource) {
  const manifest = parseReleaseManifest(manifestSource);
  return [
    '// Generated by .github/scripts/sync-version.mjs. Do not edit.',
    `MARKETING_VERSION = ${manifest.version}`,
    `CURRENT_PROJECT_VERSION = ${manifest.build}`,
    '',
  ].join('\n');
}

export function validateVersionWiring({ project, debug, release }) {
  const versionAssignment = /^\s*"?(?:MARKETING_VERSION|CURRENT_PROJECT_VERSION)(?:\[[^\]\r\n]+\])*"?\s*=/m;
  assert.ok(!versionAssignment.test(project), 'Xcode project must inherit version settings from the release manifest.');
  for (const configuration of [debug, release]) {
    assert.ok(!versionAssignment.test(configuration), 'Base configurations must not duplicate generated version settings.');
    const includes = configuration.split('\n').filter((line) => line.trim() === '#include "Generated/Version.xcconfig"');
    assert.equal(includes.length, 1, 'Each base configuration must include the generated version exactly once.');
  }
}

export async function readReleaseManifest({ rootDirectory = repositoryRoot } = {}) {
  return parseReleaseManifest(await readFile(resolve(rootDirectory, manifestPath), 'utf8'));
}

export async function syncXcodeVersion({ check = false, rootDirectory = repositoryRoot } = {}) {
  const expected = renderXcodeVersionConfiguration(await readFile(resolve(rootDirectory, manifestPath), 'utf8'));
  const target = resolve(rootDirectory, generatedPath);
  let actual;
  try {
    actual = await readFile(target, 'utf8');
  } catch (error) {
    if (error.code !== 'ENOENT') throw error;
  }
  if (check) {
    assert.equal(actual, expected, `${generatedPath} is out of date. Run: node .github/scripts/sync-version.mjs`);
  } else if (actual !== expected) {
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, expected, 'utf8');
  }
}

async function main() {
  const args = process.argv.slice(2);
  assert.ok(args.length <= 1 && args.every((argument) => ['--check', '--packaging-enabled'].includes(argument)),
    'Usage: node .github/scripts/sync-version.mjs [--check | --packaging-enabled]');
  if (args[0] === '--packaging-enabled') {
    console.log((await readReleaseManifest()).packagingEnabled ? 'true' : 'false');
  } else {
    await syncXcodeVersion({ check: args[0] === '--check' });
    if (args[0] === '--check') {
      const [project, debug, release] = await Promise.all([
        readFile(resolve(repositoryRoot, 'Buckle.xcodeproj/project.pbxproj'), 'utf8'),
        readFile(resolve(repositoryRoot, 'Config/Debug.xcconfig'), 'utf8'),
        readFile(resolve(repositoryRoot, 'Config/Release.xcconfig'), 'utf8'),
      ]);
      validateVersionWiring({ project, debug, release });
    }
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(`::error::Version synchronization failed: ${error.message}`);
    process.exitCode = 1;
  });
}
